        "originalTitle": "Prologue",
        "deck": "ผมเริ่มเห็นว่าการโตไม่ใช่เป้าหมายในตัวเอง เมื่อชีวิตที่เล็กลงช่วยให้มองเห็นงานและความพอที่ต้องการชัดขึ้น",
